// Parsea el ICS de Blackboard y arma el mensaje con lo que vence en los próximos DIAS días.
const DIAS = 7;
const TZ = 'America/New_York'; // zona horaria de la universidad
const raw = $input.first().json.data || '';

// RFC 5545: una línea que empieza con espacio continúa la anterior
const lines = [];
for (const ln of raw.replace(/\r\n/g, '\n').split('\n')) {
  if ((ln.startsWith(' ') || ln.startsWith('\t')) && lines.length) lines[lines.length - 1] += ln.slice(1);
  else lines.push(ln);
}

const events = [];
let cur = null;
for (const ln of lines) {
  if (ln === 'BEGIN:VEVENT') cur = {};
  else if (ln === 'END:VEVENT') { if (cur) events.push(cur); cur = null; }
  else if (cur && ln.includes(':')) {
    const i = ln.indexOf(':');
    const key = ln.slice(0, i).split(';')[0];
    cur[key] = ln.slice(i + 1);
  }
}

// 'ahora' como hora de pared en TZ, para comparar contra los DTSTART (que vienen en hora local de la uni)
const wall = (d) => new Date(new Date(d).toLocaleString('en-US', { timeZone: TZ }));
const now = wall(new Date());
const horizon = new Date(now.getTime() + DIAS * 86400000);
const parse = (v) => v.endsWith('Z')
  ? wall(Date.UTC(+v.slice(0,4), +v.slice(4,6)-1, +v.slice(6,8), +v.slice(9,11), +v.slice(11,13)))
  : new Date(+v.slice(0,4), +v.slice(4,6)-1, +v.slice(6,8), +(v.slice(9,11)||0), +(v.slice(11,13)||0));

const dias = ['dom','lun','mar','mié','jue','vie','sáb'];
const meses = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
const fmt = (d) => {
  let h = d.getHours(), m = String(d.getMinutes()).padStart(2, '0'), ap = h >= 12 ? 'PM' : 'AM';
  h = h % 12 || 12;
  return `${dias[d.getDay()]} ${d.getDate()} ${meses[d.getMonth()]} ${h}:${m} ${ap}`;
};
const emoji = (d) => {
  const days = Math.floor((d - new Date(now.getFullYear(), now.getMonth(), now.getDate())) / 86400000);
  return days <= 0 ? '🔴' : days <= 2 ? '🟠' : '🟡';
};

const upcoming = events
  .filter(e => e.DTSTART)
  .map(e => ({ title: e.SUMMARY || '(sin título)', due: parse(e.DTSTART) }))
  .filter(e => e.due >= now && e.due <= horizon)
  .sort((a, b) => a.due - b.due);

const head = `📚 Blackboard · ${dias[now.getDay()]} ${now.getDate()} ${meses[now.getMonth()]} · próximos ${DIAS} días`;
const body = upcoming.length
  ? upcoming.map(e => `${emoji(e.due)} ${fmt(e.due)} · ${e.title}`).join('\n')
  : 'Nada por entregar en esta ventana 🎉';

return [{ json: { message: `${head}\n\n${body}`, count: upcoming.length, items: upcoming } }];
